import attr
from attr._make import _add_methods, _make_attr
import attr._make as m

print('attr.s is _add_methods:', attr.s is m._add_methods)
print('hasattr _make.s:', hasattr(m, 's'))

@attr.s
class C(object):
    x = attr.ib(default_value=42)

@attr.s(add_repr=False, add_hash=False, add_init=False)
class D(object):
    y = attr.ib()

@_add_methods
class E(object):
    z = _make_attr()

print('C:', repr(C()), C() == C(42), hash(C()) == hash(C(42)), attr.to_dict(C()))
print('D switches off -> no own __init__:', '__init__' not in D.__dict__, '| repr is object repr:', repr(D()) == repr(D.__new__(D)))
print('E:', repr(E()), E() == E(), attr.has(E), [a.name for a in attr.ls(E)])
" && python -m pytest -q 2>&1 | tail -3
